+/// Caches the most recent `(target_ts -> block)` answer for one binary-search call site.
+///
+/// Safe to reuse as a lower bound for a *larger or equal* `target_ts`: block timestamps
+/// are monotonic in block number, so the answer for an earlier target can only be at or
+/// below the answer for a later one. Reusing it for an *earlier* target would not be
+/// safe, which is why [`AnswerCache::seed`] refuses in that case.
+///
+/// Stored as a ratchet ([`AnswerCache::update`] only overwrites when the new `target_ts`
+/// is at or after the cached one) because `is_epoch_finalized` is called concurrently
+/// for different, not-necessarily-ordered epochs from claim.rs / challenge.rs /
+/// validate_claim.rs, so updates can arrive out of order.
+///
+/// One bounded imprecision: `find_block_by_timestamp_from` returns the head block when
+/// `target_ts` is at or past the head's timestamp, and Arbitrum timestamps are
+/// non-decreasing rather than strictly increasing. Re-seeding the *same* target later,
+/// once the chain has moved on, can therefore hand back a block that is above the first
+/// block bearing `target_ts` - but never above the last one, so the seeded answer always
+/// carries the exact same timestamp as the unseeded answer. For the epoch-end lookup
+/// that only ever selects an equal-or-later batch, i.e. it can delay a `finalized`
+/// verdict, never fabricate one. Tightening `seed` to `cached_ts < target_ts` would
+/// remove even that, but it would also disable the cache for the repeated same-epoch
+/// checks this exists to speed up.
+struct AnswerCache(std::sync::Mutex<(u64, u64)>);
+
+impl AnswerCache {
+    const fn new() -> Self {
+        Self(std::sync::Mutex::new((0, 0)))
+    }
+
+    /// A provable lower bound for `target_ts`, or 0 when nothing cached is provably
+    /// at or below it. Never returns a block that could sit above the true answer.
+    fn seed(&self, target_ts: u64) -> u64 {
+        let (cached_ts, cached_block) = match self.0.lock() {
+            Ok(guard) => *guard,
+            // A poisoned lock only means some other caller panicked mid-update; the
+            // worst case for correctness is falling back to a full search.
+            Err(poisoned) => *poisoned.into_inner(),
+        };
+        if cached_ts != 0 && cached_ts <= target_ts {
+            cached_block
+        } else {
+            0
+        }
+    }
+
+    fn update(&self, target_ts: u64, block: u64) {
+        let mut guard = match self.0.lock() {
+            Ok(guard) => guard,
+            Err(poisoned) => poisoned.into_inner(),
+        };
+        if target_ts >= guard.0 {
+            *guard = (target_ts, block);
+        }
+    }
+}
+
+/// Per-provider, not per-route: every caller passes `route.inbox_provider` (both routes
+/// clone one Arbitrum provider) and `config.ethereum_provider` (one chain-1 provider),
+/// so a single static per call site holds block numbers from a single chain. If a second
+/// L2 is ever bridged, these must become per-provider state — block numbers from two
+/// chains in one cache would produce an over-high `lo`.
+static L2_EPOCH_END_CACHE: AnswerCache = AnswerCache::new();
+static L1_BATCH_SCAN_CACHE: AnswerCache = AnswerCache::new();
+
+/// The finalized head is a valid lower bound only while its own timestamp is *strictly*
+/// before `target_ts`. Once the chain has finalized up to or past the target, the
+/// finalized block can sit above the first block at or after `target_ts` and must not be
+/// used as `lo` — returning 0 (full search) is the only safe fallback there.
+///
+/// Equality is rejected rather than accepted because Arbitrum timestamps are
+/// non-decreasing, not strictly increasing: several blocks can carry `target_ts`, and
+/// `finalized` may be any of them. Rejecting costs one full search in a case that is
+/// already rare (the finalized head is ~13 min behind, epoch ends are older than that
+/// by the time they are checked), and buys a strict `lo < answer` guarantee on every
+/// chain.
+const fn finalized_floor(finalized_ts: u64, finalized_block: u64, target_ts: u64) -> u64 {
+    if finalized_ts < target_ts {
+        finalized_block
+    } else {
+        0
+    }
+}
+
+/// Seed selection, split out from the RPC so it can be unit-tested: the cached previous
+/// answer when it is usable, otherwise the finalized head when it is provably behind the
+/// target, otherwise 0 (search the whole chain).
+///
+/// `finalized` is `None` when the node has no finalized block or the call failed; an
+/// unavailable floor only costs a full search, so it is never worth retrying here.
+const fn pick_seed(cached: u64, finalized: Option<(u64, u64)>, target_ts: u64) -> u64 {
+    if cached > 0 {
+        return cached;
+    }
+    match finalized {
+        Some((finalized_ts, finalized_block)) => {
+            finalized_floor(finalized_ts, finalized_block, target_ts)
+        }
+        None => 0,
+    }
+}
+
+/// A lower bound for a binary search targeting `target_ts`, at or below the true answer
+/// (see [`AnswerCache`] for the one bounded, conservative exception on the cache path).
+async fn seed_lower_bound(
+    provider: &DynProvider<Ethereum>,
+    cache: &AnswerCache,
+    target_ts: u64,
+) -> u64 {
+    let cached = cache.seed(target_ts);
+    // Skip the `finalized` round-trip entirely when the cache already answers; this is
+    // the steady-state path.
+    if cached > 0 {
+        return cached;
+    }
