use alloy::primitives::U256;
use alloy::providers::Provider;
use std::sync::{Arc, Mutex};
use tracing::{info, warn, error};
use crate::config::{Route, ValidatorConfig};
use crate::contracts::{IVeaInbox, IVeaOutboxArbToEth, IVeaOutboxArbToGnosis, IWETH};
use crate::finality::is_epoch_finalized;
use crate::tasks::{send_or_replace, was_event_emitted, ClaimStore, TaskStore};

pub async fn execute(
    config: &ValidatorConfig,
    route: &Route,
    epoch: u64,
    claim_store: &Arc<Mutex<ClaimStore>>,
    task_store: &Arc<Mutex<TaskStore>>,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let inbox = IVeaInbox::new(route.inbox_address, route.inbox_provider.clone());
    let epoch_period: u64 = inbox.epochPeriod().call().await?.try_into()?;

    let finalized = is_epoch_finalized(
        epoch,
        epoch_period,
        &route.inbox_provider,
        &config.ethereum_provider,
        config.sequencer_inbox,
    ).await?;
    if !finalized {
        warn!(logger = "Challenge", route = route.name, epoch, "Epoch not yet finalized on L1");
        return Err("EpochNotFinalized".into());
    }

    let claim = claim_store.lock().unwrap().get_claim(epoch);
    let wallet_address = config.wallet.default_signer().address();

    let result = if let Some(weth_address) = route.weth_address {
        let outbox = IVeaOutboxArbToGnosis::new(route.outbox_address, route.outbox_provider.clone());
        let deposit = outbox.deposit().call().await?;

        let weth = IWETH::new(weth_address, route.outbox_provider.clone());
        let balance = weth.balanceOf(wallet_address).call().await?;
        if balance < deposit {
            error!(logger = "Challenge", route = route.name, epoch, have = %balance, need = %deposit, "Insufficient WETH, will retry");
            return Err("Insufficient funds".into());
        }

        send_or_replace(
            outbox.challenge(U256::from(epoch), claim),
            &route.outbox_provider,
            wallet_address,
            task_store,
            epoch,
            "challenge",
            route.name,
        ).await
    } else {
        let outbox = IVeaOutboxArbToEth::new(route.outbox_address, route.outbox_provider.clone());
        let deposit = outbox.deposit().call().await?;

        let balance = route.outbox_provider.get_balance(wallet_address).await?;
        if balance < deposit {
            error!(logger = "Challenge", route = route.name, epoch, have = %balance, need = %deposit, "Insufficient ETH, will retry");
            return Err("Insufficient funds".into());
        }

        send_or_replace(
            outbox.challenge(U256::from(epoch), claim).value(deposit),
            &route.outbox_provider,
            wallet_address,
            task_store,
            epoch,
            "challenge",
            route.name,
        ).await
    };

    if let Err(e) = result {
        if e.to_string() == "PendingReplacement" {
            return Err(e);
        }
        if was_event_emitted(&route.outbox_provider, route.outbox_address, "Challenged(uint256,address)", epoch).await {
            info!(logger = "Challenge", route = route.name, epoch, "Already challenged by another validator");
            return Ok(());
        }
        if was_event_emitted(&route.outbox_provider, route.outbox_address, "VerificationStarted(uint256)", epoch).await {
            info!(logger = "Challenge", route = route.name, epoch, "Verification started, claimHash changed - will retry");
            return Err("VerificationStarted".into());
        }
        return Err(e);
    }
    Ok(())
}

/// afterwards would be unreliable: a node that has not yet seen the transaction answers
/// null, and losing the nonce would let the next cycle send a duplicate, which is the
/// exact failure this function exists to prevent.
pub async fn send_or_replace<P, D>(
    call: alloy::contract::CallBuilder<P, D, Ethereum>,
    provider: &DynProvider<Ethereum>,
    wallet_address: Address,
    task_store: &Arc<Mutex<TaskStore>>,
    epoch: u64,
    action: &str,
    route_name: &str,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>>
where
    P: Provider<Ethereum>,
    D: alloy::contract::CallDecoder,
{
    let key = pending_key(action, epoch);
    let market = provider.estimate_eip1559_fees().await?;

    // Bound to a local so the `MutexGuard` is dropped here rather than being held
    // across the awaits below, which would make this future non-`Send`.
    let existing = task_store.lock().unwrap().get_pending_tx(&key);

    let (nonce, max_fee, priority_fee) = match existing {
        Some(previous) => {
            let nonce = previous.nonce;
            if let Some(blocking) = blocking_nonce(provider, wallet_address).await {
                if blocking != nonce {
                    info!(logger = "Task", route = route_name, action, nonce, blocking, "Queued behind an earlier nonce, waiting");
                    return Err("PendingReplacement".into());
                }
            }
            match (
                crate::bumped_fee(previous.max_fee, market.max_fee_per_gas),
                crate::bumped_fee(previous.priority_fee, market.max_priority_fee_per_gas),
            ) {
                (Some(max_fee), Some(priority_fee)) => {
                    info!(logger = "Task", route = route_name, action, nonce, max_fee, "Replacing pending tx with a higher fee");
                    (nonce, max_fee, priority_fee)
                }
                _ => {
                    warn!(logger = "Task", route = route_name, action, nonce, "Fee ceiling reached, holding rather than bumping further");
                    return Err("PendingReplacement".into());
                }
            }
        }
        None => {
            let nonce = provider.get_transaction_count(wallet_address).pending().await?;
            (nonce, market.max_fee_per_gas, market.max_priority_fee_per_gas)
        }
    };

    task_store.lock().unwrap().set_pending_tx(&key, nonce, max_fee, priority_fee);

    let sent = call
        .nonce(nonce)
        .max_fee_per_gas(max_fee)
        .max_priority_fee_per_gas(priority_fee)
        .send()
        .await;

    let pending = match sent {
        Ok(pending) => pending,
        Err(e) => {
            let msg = e.to_string();
            if msg.contains("nonce too low") {
                info!(logger = "Task", route = route_name, action, nonce, "Nonce already consumed, deferring to on-chain checks");
                task_store.lock().unwrap().clear_pending_tx(&key);
                return Err("NonceConsumed".into());
            }
            if msg.contains("replacement transaction underpriced") {
                warn!(logger = "Task", route = route_name, action, nonce, "Replacement underpriced, bumping further next cycle");
                return Err("PendingReplacement".into());
            }
            // Anything else may or may not have reached a mempool, so the record stays:
            // a stale one is harmless, a lost one risks a duplicate.
            return send_tx(Err(e), action, route_name).await;
        }
    };

    match pending.with_timeout(Some(RECEIPT_TIMEOUT)).get_receipt().await {
        Ok(receipt) => {
            task_store.lock().unwrap().clear_pending_tx(&key);
            if !receipt.status() {
                return Err(format!("[{}] {} reverted", route_name, action).into());
            }
            info!(logger = "Task", route = route_name, action, "Transaction succeeded");
            Ok(())
        }
        Err(e) => {
            warn!(logger = "Task", route = route_name, action, nonce, "Receipt not seen ({e}), will replace next cycle");
            Err("PendingReplacement".into())
        }
    }
}

pub async fn send_tx(
    result: Result<PendingTransactionBuilder<Ethereum>, ContractError>,
    action: &str,
    route_name: &str,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    match result {
        Ok(pending) => {
            let receipt = pending.with_timeout(Some(RECEIPT_TIMEOUT)).get_receipt().await?;
            if !receipt.status() {
                return Err(format!("[{}] {} reverted", route_name, action).into());
            }
            info!(logger = "Task", route = route_name, action, "Transaction succeeded");
